<?php
declare(strict_types=1);
function savePaidFunction(array $u,array $b):array{
 $t=$u['tenant'];$old=null;if(!empty($b['id'])){$old=record($t,'paid_functions',$b['id']);if(!$old||($old['state']??'active')==='deleted')throw new Fault('Função não encontrada.',404);if($old['version']!==($b['version']??null))throw new Fault('Função alterada. Atualize antes de salvar.',409);}
 $mode=$b['mode']??'';$treatment=$b['treatment']??'';if(!in_array($mode,['percentage','fixed'])||!in_array($treatment,['additional','replacement'])||$mode==='percentage'&&$treatment!=='additional')throw new Fault('Percentual é adicional; remuneração substitutiva exige valor fixo.');$from=day($b['from']??'');$until=empty($b['until'])?null:day($b['until']);if($until&&$until<$from)throw new Fault('Vigência inválida.');$basis=$b['basis']??null;if($mode==='percentage'&&!in_array($basis,['basic','fixed-reference']))throw new Fault('Selecione a base do percentual.');
 $r=['id'=>$old['id']??uid(),'name'=>need($b['name']??'','função',120),'mode'=>$mode,'treatment'=>$treatment,'rate'=>$mode==='percentage'?percentage($b['percent']??''):null,'amount'=>$mode==='fixed'?cents($b['amount']??''):null,'basis'=>$basis,'basisCents'=>$mode==='percentage'&&$basis==='fixed-reference'?cents($b['basisAmount']??''):null,'law'=>need($b['law']??'','fundamento da função',1000),'from'=>$from,'until'=>$until,'state'=>$old['state']??'active','history'=>$old['history']??[]];
 if($old){$previous=$old;unset($previous['history']);$r['history'][]=['action'=>'edit','previous'=>$previous,'actor'=>$u['id'],'at'=>date(DATE_ATOM)];}$r=save($t,'paid_functions',$r,$old['version']??null);audit($t,$old?'function.edit':'function.register',$r['id']);return ['id'=>$r['id']];
}
function paidFunctionStatus(array $u,array $b):array{$f=record($u['tenant'],'paid_functions',$b['functionId']??'');if(!$f||($f['state']??'active')==='deleted')throw new Fault('Função não encontrada.',404);if($f['version']!==($b['version']??null))throw new Fault('Função alterada. Atualize antes de salvar.',409);$action=$b['action']??'';$state=match($action){'deactivate'=>'deactivated','reactivate'=>'active','delete'=>'deleted',default=>throw new Fault('Ação inválida.')};$old=$f;unset($old['history']);$f['history'][]=['action'=>$action,'previous'=>$old,'reason'=>need($b['reason']??'','motivo',1000),'actor'=>$u['id'],'at'=>date(DATE_ATOM)];$f['state']=$state;save($u['tenant'],'paid_functions',$f,$f['version']);audit($u['tenant'],'function.'.$action,$f['id']);return ['ok'=>true];}
